mapper.select:
SELECT 
  FROM dcr20_relate_ics a
       INNER JOIN ics01_class_tree b ON a.dcr20_ics_class_tree_id = b.ics01_class_tree_id
 WHERE a.dcr20_company_id = #{companyId}
   AND a.dcr20_relate_ics_id IN
#{id}

mapper.delete:
DELETE FROM dcr20_relate_ics
 WHERE dcr20_dcr_class_tree_id = #{dcrClassTreeId}
   AND dcr20_ics_class_tree_id = #{icsClassTreeId}
   AND dcr20_company_id        = #{companyId}

DELETE FROM dcr20_relate_ics
 WHERE dcr20_company_id = #{companyId}
   AND dcr20_relate_ics_id IN
#{id}
